using StardewModdingAPI;\n\nnamespace EnhancedSchoolsMod\n{\n    public class DialogueHandler\n    {\n        private readonly IMonitor Monitor;\n        public DialogueHandler(IMonitor monitor) => Monitor = monitor;\n        public void GenerateChildDialogue(string childName, string schoolType, bool returningFromHoliday = false)\n        {\n            string context = returningFromHoliday ? \"holiday\" : \"school\";\n            Monitor.Log($\"{childName} returned from {schoolType} ({context}).\", LogLevel.Trace);\n        }\n        public void GenerateTermEndDialogue(string childName, string schoolType, int finalGpa)\n        {\n            Monitor.Log($\"Term end dialogue for {childName}: GPA {finalGpa}\", LogLevel.Trace);\n        }\n    }\n}